create or replace function public.rental_request_adjustment_reversal(p_adjustment uuid,p_date date,p_reason text) returns jsonb language plpgsql security definer set search_path='' as $$declare a public.rental_financial_adjustments%rowtype; rid uuid; inverse_type text; begin if auth.uid() is null or p_date is null or length(btrim(coalesce(p_reason,'')))=0 then raise exception 'An effective date and reason are required'; end if; select * into a from public.rental_financial_adjustments where id=p_adjustment for update; if not found or not exists(select 1 from public.rental_tenancies t join public.rental_properties p on p.id=t.property_id where t.id=a.tenancy_id and public.rental_branch_access(p.organisation_id,p.branch_id)) then raise exception 'You are not authorized for this adjustment'; end if; if public.rental_financial_period_is_closed(a.tenancy_id,p_date) then raise exception 'The financial period is closed'; end if; inverse_type:=case when a.adjustment_type='debit' then 'credit' else 'debit' end; insert into public.rental_financial_correction_requests(organisation_id,tenancy_id,correction_kind,adjustment_type,amount,effective_date,reason,original_adjustment_id,requested_by) values(a.organisation_id,a.tenancy_id,'adjustment_reversal',inverse_type,a.amount,p_date,btrim(p_reason),a.id,auth.uid()) returning id into rid; return jsonb_build_object('correction_id',rid,'status','pending','amount',a.amount); end$$; revoke execute on function public.rental_request_adjustment_reversal(uuid,date,text) from public,anon; grant execute on function public.rental_request_adjustment_reversal(uuid,date,text) to authenticated;;
